<?php
function clay_moderation_notice_text(array $log): string {
    $name = trim((string)($log['admin_name'] ?? '版主')) ?: '版主';
    $action = (string)($log['action'] ?? '');
    $detail = json_decode((string)($log['detail'] ?? ''), true) ?: [];
    return match ($action) {
        'thread.featured' => !empty($detail['enabled']) ? '本帖已由 ' . $name . ' 设为精华' : '本帖已由 ' . $name . ' 取消精华',
        'thread.recommended' => !empty($detail['enabled']) ? '本帖已由 ' . $name . ' 设为推荐' : '本帖已由 ' . $name . ' 取消推荐',
        'thread.locked' => !empty($detail['enabled']) ? '本帖已由 ' . $name . ' 锁定回复' : '本帖已由 ' . $name . ' 解除锁定',
        'thread.top' => (($detail['scope'] ?? 'none') === 'none') ? '本帖已由 ' . $name . ' 取消置顶' : '本帖已由 ' . $name . ' 设为置顶',
        'thread.move' => '本帖已由 ' . $name . ' 移动板块',
        'thread.status' => '本帖状态已由 ' . $name . ' 调整',
        default => '',
    };
}
