<?php if (!empty($thread['id'])): ?><script>
(function(){
  var rail=document.getElementById('readProgressRail'), text=document.getElementById('readProgressText');
  if(!rail||!text)return;
  var tid=<?= (int)$thread['id'] ?>, csrf=<?= json_encode(csrf_token()) ?>, canSave=<?= $viewer ? 'true' : 'false' ?>;
  var saved=<?= (int)($readProgress['progress'] ?? 0) ?>, lastPaint=-1, saveTimer=null;
  function calc(){
    var target=document.querySelector('.post-body .rich-content') || document.querySelector('.post-body');
    if(!target)return 0;
    var rect=target.getBoundingClientRect();
    var viewport=window.innerHeight||document.documentElement.clientHeight||1;
    var targetTop=(window.scrollY||window.pageYOffset||0)+rect.top;
    var targetHeight=Math.max(1,target.scrollHeight||rect.height||1);
    var start=targetTop;
    var end=targetTop+targetHeight-viewport;
    if(targetHeight<=viewport){
      var visible=Math.min(rect.bottom,viewport)-Math.max(rect.top,0);
      return visible>0?100:((window.scrollY||window.pageYOffset||0)<start?0:100);
    }
    var current=window.scrollY||window.pageYOffset||0;
    var p=(current-start)/Math.max(1,end-start)*100;
    return Math.max(0,Math.min(100,Math.round(p)));
  }
  function paint(p){
    if(p===lastPaint)return;
    lastPaint=p;
    rail.style.setProperty('--read-progress',p+'%');
    text.textContent=p+'%';
  }
  function save(p,force){
    if(!canSave)return;
    if(!force && p<saved+10 && p<98)return;
    saved=Math.max(saved,p);
    var fd=new FormData();fd.append('_csrf_token',csrf);fd.append('thread_id',tid);fd.append('progress',p);var lp=null;document.querySelectorAll('.comment-item[id^=post-]').forEach(function(el){var r=el.getBoundingClientRect();if(r.top<window.innerHeight*0.65)lp=el.id.replace('post-','');});if(lp)fd.append('last_post_id',lp);
    fetch('/index.php?path=thread/read-progress',{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}).catch(function(){});
  }
  function update(){
    var p=calc();
    paint(p);
    clearTimeout(saveTimer);
    saveTimer=setTimeout(function(){save(p,false);},650);
  }
  addEventListener('scroll',function(){requestAnimationFrame(update);},{passive:true});
  addEventListener('resize',function(){requestAnimationFrame(update);},{passive:true});
  addEventListener('beforeunload',function(){save(calc(),true);});
  update();
  setTimeout(update,500);
})();
</script><?php endif; ?>
