<script>
(function(){
  var pop=null, timer=null;
  function ensurePop(){
    if(pop) return pop;
    pop=document.createElement('div');
    pop.className='clay-medal-popover';
    pop.setAttribute('role','status');
    pop.setAttribute('aria-live','polite');
    document.body.appendChild(pop);
    return pop;
  }
  function showMedal(btn){
    var name=btn.getAttribute('data-medal-name')||btn.getAttribute('aria-label')||btn.getAttribute('title')||'';
    if(!name) return;
    var p=ensurePop();
    p.textContent=name;
    p.classList.add('is-open');
    var r=btn.getBoundingClientRect();
    var left=Math.max(42,Math.min(window.innerWidth-42,r.left+r.width/2));
    var top=Math.max(40,r.top-8);
    p.style.left=left+'px';
    p.style.top=top+'px';
    clearTimeout(timer);
    timer=setTimeout(hideMedal,1800);
  }
  function hideMedal(){
    if(pop) pop.classList.remove('is-open');
  }
  document.addEventListener('click',function(e){
    var btn=e.target.closest('.thread-time-medals .clay-user-medal.is-icon-only,.author-card-medal-list .clay-user-medal.is-icon-only');
    if(!btn){hideMedal();return;}
    e.preventDefault();
    e.stopPropagation();
    showMedal(btn);
  });
  document.addEventListener('keydown',function(e){if(e.key==='Escape')hideMedal();});
  window.addEventListener('scroll',hideMedal,{passive:true});
})();
</script>
