(function(){var modal=document.getElementById('threadManageModal');if(!modal)return;var pinModal=document.getElementById('threadPinModal'),pinForm=null,moveModal=document.getElementById('threadMoveModal'),moveForm=null;function closePin(){if(pinModal){pinModal.classList.remove('is-open');pinModal.setAttribute('aria-hidden','true');}pinForm=null;}function closeMove(){if(moveModal){moveModal.classList.remove('is-open');moveModal.setAttribute('aria-hidden','true');}moveForm=null;}function submitPin(action){if(!pinForm)return;var input=pinForm.querySelector('input[name="moderation_action"][data-pin-submit]');if(!input){input=document.createElement('input');input.type='hidden';input.name='moderation_action';input.setAttribute('data-pin-submit','1');pinForm.appendChild(input);}input.value=action;if(pinForm.requestSubmit)pinForm.requestSubmit();else pinForm.submit();}function submitMove(){if(!moveForm)return;var sel=document.getElementById('threadMoveSection');if(!sel||parseInt(sel.value||'0',10)<=0){alert('请选择目标板块');return;}var target=moveForm.querySelector('input[name="target_section_id"][data-move-submit]');if(!target){target=document.createElement('input');target.type='hidden';target.name='target_section_id';target.setAttribute('data-move-submit','1');moveForm.appendChild(target);}target.value=sel.value;var action=moveForm.querySelector('input[name="moderation_action"][data-move-submit]');if(!action){action=document.createElement('input');action.type='hidden';action.name='moderation_action';action.setAttribute('data-move-submit','1');moveForm.appendChild(action);}action.value='move';if(moveForm.requestSubmit)moveForm.requestSubmit();else moveForm.submit();}document.addEventListener('click',function(e){var moveBtn=e.target.closest('[data-move-open]');if(moveBtn){moveForm=moveBtn.closest('form');if(moveModal){moveModal.classList.add('is-open');moveModal.setAttribute('aria-hidden','false');}return;}if(e.target.closest('[data-move-confirm]')){submitMove();closeMove();return;}if(e.target.closest('[data-move-cancel]')){closeMove();return;}var pinBtn=e.target.closest('[data-pin-open]');if(pinBtn){pinForm=pinBtn.closest('form');if(pinModal){pinModal.classList.add('is-open');pinModal.setAttribute('aria-hidden','false');}return;}var pinAction=e.target.closest('[data-pin-action]');if(pinAction){submitPin(pinAction.getAttribute('data-pin-action')||'');closePin();return;}if(e.target.closest('[data-pin-cancel]')){closePin();return;}if(e.target.closest('[data-manage-open]')){modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');}if(e.target.closest('[data-manage-close]')){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');closePin();closeMove();}});})();
(function(){var currentPage=1,totalPages=1,threadId=<?= (int)($thread['id'] ?? 0) ?>;function openModal(id){var m=document.getElementById(id);if(!m)return;m.classList.add('is-open');m.setAttribute('aria-hidden','false');if(id==='rewardListModal')loadPage(currentPage);}function closeModal(el){var m=el.closest('.reward-modal');if(!m)return;m.classList.remove('is-open');m.setAttribute('aria-hidden','true');}function avatarHtml(row){var v='';if(row.verification_name){var color=String(row.verification_color||'#2563eb');if(!/^#[0-9a-fA-F]{6}$/.test(color))color='#2563eb';v='<span class="user-verify-v avatar-verify-badge" title="'+escapeHtml(row.verification_name)+'" style="--verify-color:'+escapeHtml(color)+'">V</span>';}if(row.avatar){return '<span class="avatar-verify-wrap" style="--avatar-size:30px;"><span class="oc-avatar has-image"><img src="'+escapeHtml(row.avatar)+'" alt="'+escapeHtml(row.name)+'"></span>'+v+'</span>';}return '<span class="avatar-verify-wrap" style="--avatar-size:30px;"><span class="oc-avatar">'+escapeHtml((row.name||'用').slice(0,1))+'</span>'+v+'</span>';}function escapeHtml(str){return String(str||'').replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c];});}function renderRows(rows){var box=document.getElementById('reward-rank-list');if(!box)return;if(!rows||!rows.length){box.innerHTML='<div class="comment-empty" style="padding:22px 0;">暂无打赏记录</div>';return;}box.innerHTML=rows.map(function(row){return '<div class="reward-rank-row"><div class="reward-rank">#'+row.rank+'</div>'+avatarHtml(row)+'<div><div class="reward-rank-name">'+escapeHtml(row.name)+' '+(row.level_badge||'')+'</div><div class="reward-rank-meta">打赏 '+(row.reward_count||0)+' 次</div></div><div class="reward-rank-amount">'+escapeHtml(row.amount_label)+'</div></div>';}).join('');}function updatePager(){var info=document.getElementById('reward-page-info'),prev=document.getElementById('reward-prev'),next=document.getElementById('reward-next');if(info)info.textContent=currentPage+' / '+totalPages;if(prev)prev.disabled=currentPage<=1;if(next)next.disabled=currentPage>=totalPages;}function loadPage(page){fetch('/index.php?path=thread/rewards&thread_id='+threadId+'&page='+page,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json();}).then(function(data){if(!data.ok)return;currentPage=data.page||1;totalPages=data.total_pages||1;renderRows(data.rows||[]);updatePager();}).catch(function(){updatePager();});}document.addEventListener('click',function(e){var opener=e.target.closest('[data-reward-open]');if(opener){openModal(opener.dataset.rewardOpen);return;}if(e.target.closest('[data-reward-close]')){closeModal(e.target);return;}if(e.target&&e.target.id==='reward-prev'&&currentPage>1){loadPage(currentPage-1);return;}if(e.target&&e.target.id==='reward-next'&&currentPage<totalPages){loadPage(currentPage+1);return;}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){document.querySelectorAll('.reward-modal.is-open').forEach(function(m){m.classList.remove('is-open');m.setAttribute('aria-hidden','true');});}});var sel=document.getElementById('reward-currency-select'),tip=document.getElementById('reward-balance-tip'),amount=document.querySelector('#rewardSendModal input[name=amount]');function updateTip(){if(!sel||!tip)return;var opt=sel.options[sel.selectedIndex];if(!opt){tip.textContent='暂无可用货币。';return;}var precision=parseInt(opt.dataset.precision||'0',10),balance=parseFloat(opt.dataset.balance||'0'),symbol=opt.dataset.symbol||'';tip.textContent='当前可用余额：'+balance.toFixed(Math.max(0,precision));if(amount){amount.step=precision>0?String(1/Math.pow(10,precision)):'1';amount.min=precision>0?amount.step:'1';}}if(sel){sel.addEventListener('change',updateTip);updateTip();}updatePager();})();


(function(){
  var modal=document.getElementById('threadReasonModal');
  var input=document.getElementById('threadReasonInput');
  var title=document.getElementById('threadReasonTitle');
  var pending=null;
  function submitReason(ctx, reason){
    var form=ctx.form, action=ctx.action, fieldName=ctx.fieldName;
    var field=form.querySelector('input[name="'+fieldName+'"]');
    if(field) field.value=reason||'';
    var actionInput=form.querySelector('input[name="moderation_action"][data-reason-submit]');
    if(!actionInput){actionInput=document.createElement('input');actionInput.type='hidden';actionInput.name='moderation_action';actionInput.setAttribute('data-reason-submit','1');form.appendChild(actionInput);}
    actionInput.value=action;
    if(form.requestSubmit) form.requestSubmit(); else form.submit();
  }
  function closeReason(){if(modal){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');} pending=null;}
  document.querySelectorAll('[data-reason-action]').forEach(function(btn){
    btn.addEventListener('click',function(){
      var form=btn.closest('form'); if(!form) return;
      var ctx={form:form,action:btn.getAttribute('data-reason-action')||'',fieldName:btn.getAttribute('data-reason-field')||''};
      var isCancel=(btn.textContent||'').indexOf('取消')!==-1;
      if(isCancel){submitReason(ctx,'');return;}
      pending=ctx;
      if(title) title.textContent=(ctx.action==='featured'?'精华理由':'推荐理由');
      if(input){input.value=btn.getAttribute('data-reason-current')||'';input.placeholder=btn.getAttribute('data-reason-prompt')||'请输入理由，可留空';}
      if(modal){modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');setTimeout(function(){input&&input.focus();},30);} else {submitReason(ctx,'');}
    });
  });
  document.querySelectorAll('[data-reason-cancel]').forEach(function(el){el.addEventListener('click',closeReason);});
  var ok=document.querySelector('[data-reason-confirm]');
  if(ok) ok.addEventListener('click',function(){if(!pending)return;submitReason(pending,input?input.value:'');closeReason();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&modal&&modal.classList.contains('is-open'))closeReason();});
})();
</script>
